content.query:
let raw = trim(@"\s+", "{TraceId}");
let wanted = iff(raw startswith "00-", tostring(split(raw, "-")[1]), raw);
union requests, dependencies, traces, exceptions
| where operation_Id == wanted
| project timestamp, itemType, name, resultCode, duration, url, message
| order by timestamp asc

requests
| where name == "POST /api/links/" and resultCode == "429"
| make-series rejected = count() default = 0 on timestamp from {TimeRange:start} to {TimeRange:end} step {TimeRange:grain}

let errors = toscalar(requests | where toint(resultCode) >= 500 | count);
let dropped = toscalar(customMetrics | where name == "urlshortener.analytics.dropped_clicks" | summarize sum(valueSum));
print ["5xx responses (all routes)"] = errors, ["dropped clicks"] = coalesce(dropped, 0.0)
